PRAGMA foreign_keys=ON;
CREATE TABLE IF NOT EXISTS users(id TEXT PRIMARY KEY,telegram_user_id TEXT UNIQUE,display_name TEXT NOT NULL,username TEXT,created_at TEXT NOT NULL DEFAULT(datetime('now')),updated_at TEXT NOT NULL DEFAULT(datetime('now')));
CREATE TABLE IF NOT EXISTS courses(id TEXT PRIMARY KEY,title TEXT NOT NULL,description TEXT,source_language TEXT NOT NULL DEFAULT 'fa',target_language TEXT NOT NULL DEFAULT 'en',status TEXT NOT NULL CHECK(status IN('draft','published','archived')),created_at TEXT NOT NULL DEFAULT(datetime('now')),updated_at TEXT NOT NULL DEFAULT(datetime('now')));
CREATE TABLE IF NOT EXISTS lessons(id TEXT PRIMARY KEY,course_id TEXT NOT NULL REFERENCES courses(id) ON DELETE CASCADE,title TEXT NOT NULL,description TEXT,level TEXT NOT NULL DEFAULT 'A1',position INTEGER NOT NULL,version INTEGER NOT NULL DEFAULT 1,status TEXT NOT NULL CHECK(status IN('draft','published','archived')),created_at TEXT NOT NULL DEFAULT(datetime('now')),updated_at TEXT NOT NULL DEFAULT(datetime('now')),UNIQUE(course_id,position));
CREATE TABLE IF NOT EXISTS questions(id TEXT PRIMARY KEY,lesson_id TEXT NOT NULL REFERENCES lessons(id) ON DELETE CASCADE,type TEXT NOT NULL CHECK(type='multiple_choice'),prompt TEXT NOT NULL,options_json TEXT NOT NULL,answer_key TEXT NOT NULL,explanation TEXT NOT NULL,position INTEGER NOT NULL,status TEXT NOT NULL CHECK(status IN('draft','published','archived')),UNIQUE(lesson_id,position));
CREATE TABLE IF NOT EXISTS lesson_attempts(id TEXT PRIMARY KEY,user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,lesson_id TEXT NOT NULL REFERENCES lessons(id),status TEXT NOT NULL CHECK(status IN('in_progress','completed','abandoned')),score INTEGER CHECK(score BETWEEN 0 AND 100),started_at TEXT NOT NULL DEFAULT(datetime('now')),completed_at TEXT);
CREATE TABLE IF NOT EXISTS attempt_answers(id TEXT PRIMARY KEY,attempt_id TEXT NOT NULL REFERENCES lesson_attempts(id) ON DELETE CASCADE,question_id TEXT NOT NULL REFERENCES questions(id),submitted_answer TEXT NOT NULL,is_correct INTEGER NOT NULL CHECK(is_correct IN(0,1)),answered_at TEXT NOT NULL DEFAULT(datetime('now')),UNIQUE(attempt_id,question_id));
CREATE TABLE IF NOT EXISTS user_progress(user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,lesson_id TEXT NOT NULL REFERENCES lessons(id) ON DELETE CASCADE,best_score INTEGER NOT NULL DEFAULT 0 CHECK(best_score BETWEEN 0 AND 100),completed_count INTEGER NOT NULL DEFAULT 0,last_completed_at TEXT,PRIMARY KEY(user_id,lesson_id));
CREATE INDEX IF NOT EXISTS idx_lessons_course_status_position ON lessons(course_id,status,position);
CREATE INDEX IF NOT EXISTS idx_questions_lesson_status_position ON questions(lesson_id,status,position);
CREATE INDEX IF NOT EXISTS idx_attempts_user_started ON lesson_attempts(user_id,started_at DESC);
CREATE INDEX IF NOT EXISTS idx_progress_user ON user_progress(user_id);